# Hypothesis: each non-5 value gets replaced by its number of non-5 neighbors

grid = [
    [5, 5, 5, 5, 1, 5],
    [5, 5, 0, 5, 5, 5],
    [5, 5, 5, 5, 5, 5],
    [0, 5, 0, 5, 5, 5],
    [0, 0, 0, 5, 5, 5],
    [5, 0, 5, 0, 5, 5]
]

def count_neighbors(grid, r, c):
    """Count non-5 neighbors (up, down, left, right)"""
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 6 and 0 <= nc < 6:
            if grid[nr][nc] != 5:
                count += 1
    return count

output = []
for r in range(6):
    row = []
    for c in range(6):
        if grid[r][c] != 5:
            row.append(count_neighbors(grid, r, c))
        else:
            row.append(5)
    output.append(row)

print("Hypothesis - replace with neighbor count:")
for row in output:
    print(row)
print(json.dumps({"action": "submit", "grid": output}))

